import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';

const ChatListPage = () => {
  const [user, setUser] = useState(null);
  const [chats, setChats] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      const q = query(
        collection(db, 'chats'),
        where('userId', '==', user.uid)
      );
      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const chatList = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setChats(chatList);
      });
      return () => unsubscribe();
    }
  }, [user]);

  const handleChatClick = (chat) => {
    navigate(`/chat/${chat.postId}`, { state: { listing: chat.listing } });
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-semibold mb-4">Chats</h1>
      <div className="bg-white p-4 rounded-lg shadow-md">
        {chats.map((chat) => (
          <div
            key={chat.id}
            className="mb-2 p-2 rounded-lg bg-gray-100 cursor-pointer"
            onClick={() => handleChatClick(chat)}
          >
            <p className="text-sm"><strong>{chat.listing.title}</strong></p>
            <p className="text-sm text-gray-600">{chat.message}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ChatListPage;
